 99→export function ChatBot({ isOpen, onClose }: ChatBotProps) {
100→  // Get visitor archetype and event recorder from perception system
101→  const { archetype, confidence, recordEvent } = usePerception();
102→
103→  const getInitialMessage = (): string => {
104→    return "What would you like to know about Joseph's work?";
105→  };
106→
107→  const [messages, setMessages] = useState<Message[]>([
108→    { type: 'bot', text: getInitialMessage() }
109→  ]);
110→  const [inputValue, setInputValue] = useState('');
111→  const [isTyping, setIsTyping] = useState(false);
112→  const [hasConversation, setHasConversation] = useState(false);
113→
114→  // Track timing for response read time calculation
115→  const lastBotResponseTimeRef = useRef<number>(0);
116→  const userMessageCountRef = useRef<number>(0);
117→
118→  const inputRef = useRef<HTMLInputElement>(null);
119→  const messagesEndRef = useRef<HTMLDivElement>(null);
120→  const isMountedRef = useRef(true);
121→  const abortControllerRef = useRef<AbortController | null>(null);
122→
123→  // Track mounted state
124→  useEffect(() => {
125→    isMountedRef.current = true;
126→    return () => {
127→      isMountedRef.current = false;
128→      if (abortControllerRef.current) {
129→        abortControllerRef.current.abort();
130→      }
131→    };
132→  }, []);
133→
134→  // Focus input when chatbot opens
135→  useEffect(() => {
136→    if (isOpen && inputRef.current) {
137→      const focusTimeout = setTimeout(() => {
138→        if (isMountedRef.current && inputRef.current) {
139→          inputRef.current.focus();
140→        }
141→      }, 100);
142→      return () => clearTimeout(focusTimeout);
143→    }
144→  }, [isOpen]);
145→
146→  // Scroll to bottom when new messages arrive
147→  useEffect(() => {
148→    if (messagesEndRef.current) {
149→      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
150→    }
151→  }, [messages, isTyping]);
152→
153→  // Handle escape key to close
154→  useEffect(() => {
155→    const handleEscape = (e: KeyboardEvent) => {
156→      if (e.key === 'Escape' && isOpen) {
157→        onClose();
158→      }
159→    };
160→    document.addEventListener('keydown', handleEscape);
161→    return () => document.removeEventListener('keydown', handleEscape);
162→  }, [isOpen, onClose]);
163→
164→  // Reset on open
165→  useEffect(() => {
166→    if (isOpen) {
167→      setMessages([{ type: 'bot', text: getInitialMessage() }]);
168→      setInputValue('');
169→      setIsTyping(false);
170→      setHasConversation(false);
171→      // Reset chat tracking for perception system
172→      lastBotResponseTimeRef.current = 0;
173→      userMessageCountRef.current = 0;
174→      if (abortControllerRef.current) {
175→        abortControllerRef.current.abort();
176→        abortControllerRef.current = null;
177→      }
178→      document.body.setAttribute('data-chatbot-open', 'true');
179→    } else {
180→      document.body.removeAttribute('data-chatbot-open');
181→    }
182→  }, [isOpen]);
183→
184→  // Send message to AI and stream response
185→  const sendMessage = useCallback(async (query: string) => {
186→    if (!query.trim() || isTyping) return;
187→
188→    // Record response read time if this isn't the first message
189→    if (lastBotResponseTimeRef.current > 0) {
190→      const responseReadTime = Date.now() - lastBotResponseTimeRef.current;
191→      recordEvent({
192→        timestamp: Date.now(),
193→        type: SensorEventType.CHAT_RESPONSE_READ,
194→        data: {
195→          responseReadTime,
196→        },
197→      });
198→    }
199→
200→    // Analyze the message for behavioral signals
201→    const isFollowUp = userMessageCountRef.current > 0;
202→    const messageAnalysis = analyzeChatMessage(query, isFollowUp);
203→    userMessageCountRef.current++;
204→
205→    // Record the chat message event
206→    recordEvent({
207→      timestamp: Date.now(),
208→      type: SensorEventType.CHAT_MESSAGE,
209→      data: {
210→        messageLength: messageAnalysis.messageLength,
211→        wordCount: messageAnalysis.wordCount,
212→        hasTechnicalTerms: messageAnalysis.hasTechnicalTerms,
213→        isFollowUp: messageAnalysis.isFollowUp,
214→        questionCategory: messageAnalysis.questionCategory,
215→      },
216→    });
217→
218→    // Add user message
219→    const userMessage: Message = { type: 'user', text: query };
220→    setMessages(prev => [...prev, userMessage]);
221→    setInputValue('');
222→    setIsTyping(true);
223→    setHasConversation(true);
224→
225→    // Abort any existing request
226→    if (abortControllerRef.current) {
227→      abortControllerRef.current.abort();
228→    }
229→    abortControllerRef.current = new AbortController();
230→
231→    try {
232→      // Get conversation history (excluding the message we just added)
233→      const conversationHistory = messages.map(m => ({
234→        type: m.type,
235→        text: m.text
236→      }));
237→
238→      // Server handles model selection deterministically based on environment
239→      // (Anthropic in production, Ollama locally)
240→      // Visitor context enables archetype-aware response adaptation
241→      const response = await fetch('/api/ai-chat', {
242→        method: 'POST',
243→        headers: { 'Content-Type': 'application/json' },
244→        body: JSON.stringify({
245→          message: query,
246→          messages: conversationHistory,
247→          stream: true,
248→          context: 'portfolio',
249→          // Perception context for invisible adaptation
250→          visitor: {
251→            archetype: archetype ?? 'unknown',
252→            confidence: confidence ?? 0,
253→          },
254→        }),
255→        signal: abortControllerRef.current.signal
256→      });
257→
258→      if (!response.ok) {
259→        throw new Error(`API error: ${response.status}`);
260→      }
261→
262→      // Add empty bot message that we'll stream into
263→      const botMessageIndex = messages.length + 1; // +1 for user message we just added
264→      setMessages(prev => [...prev, { type: 'bot', text: '', isStreaming: true }]);
265→
266→      // Stream the response
267→      const reader = response.body?.getReader();
268→      if (!reader) throw new Error('No response body');
269→
270→      const decoder = new TextDecoder();
271→      let fullText = '';
272→
273→      while (true) {
274→        const { done, value } = await reader.read();
275→        if (done) break;
276→
277→        const chunk = decoder.decode(value, { stream: true });
278→        fullText += chunk;
279→
280→        // Update the bot message with streamed content
281→        // Optimization: only clone the last element, reuse the rest of the array
282→        if (isMountedRef.current) {
283→          setMessages(prev => {
284→            const lastIndex = prev.length - 1;
285→            if (prev[lastIndex]?.type === 'bot') {
286→              const updated = prev.slice(0, lastIndex);
287→              updated.push({ type: 'bot', text: fullText, isStreaming: true });
288→              return updated;
289→            }
290→            return prev;
291→          });
292→        }
293→      }
294→
295→      // Mark streaming as complete
296→      if (isMountedRef.current) {
297→        setMessages(prev => {
298→          const lastIndex = prev.length - 1;
299→          if (prev[lastIndex]?.type === 'bot') {
300→            const updated = prev.slice(0, lastIndex);
301→            updated.push({ type: 'bot', text: fullText, isStreaming: false });
302→            return updated;
303→          }
304→          return prev;
305→        });
306→        setIsTyping(false);
307→        // Track when bot response completed (for read time calculation)
308→        lastBotResponseTimeRef.current = Date.now();
309→      }
310→
311→    } catch (error) {
312→      if (error instanceof Error && error.name === 'AbortError') {
313→        // Request was aborted, ignore
314→        return;
315→      }
316→
317→      console.error('Chat error:', error);
318→
319→      // Add fallback error message
320→      if (isMountedRef.current) {
321→        setMessages(prev => [...prev, {
322→          type: 'bot',
323→          text: "I'm having trouble connecting right now. You can reach Joseph directly at jomar.ibrahim@gmail.com for any questions about his work or availability."
324→        }]);
325→        setIsTyping(false);
326→      }
327→    }
328→  }, [messages, isTyping, archetype, confidence, recordEvent]);
329→
330→  // Handle form submit
331→  const handleSubmit = useCallback((e: React.FormEvent) => {
332→    e.preventDefault();
333→    sendMessage(inputValue);
334→  }, [inputValue, sendMessage]);
335→
336→  // Handle quick reply click
337→  const handleQuickReply = useCallback((question: string) => {
338→    if (!isTyping) {
339→      sendMessage(question);
340→    }
341→  }, [isTyping, sendMessage]);
342→
343→  if (!isOpen) return null;
344→
345→  const isInitialState = messages.length === 1 && messages[0].type === 'bot';
346→  const currentSuggestions = hasConversation ? FOLLOW_UP_SUGGESTIONS : INITIAL_SUGGESTIONS;
347→
348→  return (
349→    <div
350→      role="dialog"
351→      aria-modal="true"
352→      aria-label="Chat with Joseph Ibrahim"
353→      className="fixed inset-0 flex items-center justify-center"
354→      onClick={onClose}
355→      style={{
356→        backgroundColor: '#141414',
357→        zIndex: 200,
358→        animation: 'chatFadeIn 250ms ease-out'
359→      }}
360→    >
361→      {/* Close button */}
362→      <button
363→        onClick={onClose}
